def _read_records(text):
    row = []
    field = []
    state = "start"
    quoted = False
    i = 0

    def finish_field():
        value = "".join(field)
        row.append(value if quoted else value.strip(" \t"))
        field.clear()

    while i < len(text):
        char = text[i]

        if state == "quoted":
            if char == '"':
                if i + 1 < len(text) and text[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                state = "closed"
            else:
                field.append(char)
        elif char == ",":
            finish_field()
            state = "start"
            quoted = False
        elif char in "\r\n":
            if row or state != "start":
                finish_field()
            yield row
            row = []
            state = "start"
            quoted = False
            if char == "\r" and i + 1 < len(text) and text[i + 1] == "\n":
                i += 1
        elif state == "start":
            if char == '"':
                quoted = True
                state = "quoted"
            elif char not in " \t":
                field.append(char)
                state = "unquoted"
        elif state == "closed":
            if char not in " \t":
                field.append(char)
                state = "unquoted"
        else:
            field.append(char)

        i += 1

    if row or state != "start":
        finish_field()
        yield row


def parse_csv(raw_csv: str):
    expected_width = 6
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]
    records = list(_read_records(raw_csv))

    header_index = next(
        (i for i, record in enumerate(records)
         if len(record) == expected_width and any(record)),
        None,
    )
    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records) if len(record) > 1 and any(record)),
            None,
        )
    if header_index is None:
        header_index = next(
            (i for i, record in enumerate(records) if any(record)),
            None,
        )
    if header_index is None:
        return {"columns": [], "rows": []}

    columns = records[header_index][:]
    if columns[0].startswith("#"):
        columns[0] = columns[0][1:].lstrip(" \t")

    rows = records[header_index + 1:]
    width = max(expected_width, len(columns), max(map(len, rows), default=0))
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        name = "column_" + str(position)
        while name in used_names:
            name += "_"
        columns.append(name)
        used_names.add(name)

    return {
        "columns": columns,
        "rows": [row + [""] * (width - len(row)) for row in rows],
    }
